"""Audit H3 uploads and persist task IDs without automatic POST retries."""
import argparse
import base64
from datetime import datetime, timezone
import hashlib
import json
import mimetypes
from pathlib import Path
import urllib.error
import urllib.parse
import urllib.request

ROOT = Path(__file__).resolve().parents[1]


def save(path, obj):
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + '.tmp')
    temp.write_text(json.dumps(obj, ensure_ascii=False, indent=2), encoding='utf-8')
    temp.replace(path)


def read(path):
    return json.loads(path.read_text(encoding='utf-8-sig'))


def now():
    return datetime.now(timezone.utc).isoformat()


def request(path, body=None):
    credential = None
    for line in (ROOT / '.env').read_text(encoding='utf-8-sig').splitlines():
        if line.startswith('AUTODL_IMAGE_KEY='):
            credential = line.split('=', 1)[1].strip().strip('\"\'')
    if not credential:
        raise RuntimeError('Credential not configured')
    headers = {'Authorization': 'Bearer ' + credential, 'User-Agent': 'Mozilla/5.0'}
    data = None
    if body is not None:
        data = json.dumps(body, ensure_ascii=False).encode('utf-8')
        headers['Content-Type'] = 'application/json'
    req = urllib.request.Request('https://www.autodl.art' + path, data=data, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=55) as response:
            return response.status, json.loads(response.read().decode('utf-8'))
    except urllib.error.HTTPError as error:
        raw = error.read().decode('utf-8', errors='replace')
        try:
            result = json.loads(raw)
        except json.JSONDecodeError:
            result = {'http_error': raw[:2000]}
        return error.code, result


def verify_video_url(url, source):
    parsed = urllib.parse.urlsplit(url)
    if parsed.scheme != 'https' or not parsed.hostname or parsed.username or parsed.password:
        raise ValueError('Reference video needs a public HTTPS URL without embedded credentials')
    if not urllib.parse.unquote(parsed.path).lower().endswith('.mp4'):
        raise ValueError('This endpoint requires a reference URL with an explicit .mp4 filename')
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    digest = hashlib.sha256()
    total_bytes = 0
    with urllib.request.urlopen(req, timeout=55) as response:
        if response.status != 200:
            raise ValueError('Video URL did not return a complete file')
        content_type = response.headers.get('Content-Type', '').split(';', 1)[0].lower()
        while chunk := response.read(1024 * 1024):
            total_bytes += len(chunk)
            if total_bytes > len(source):
                raise ValueError('Hosted video does not match the supplied source file')
            digest.update(chunk)
    if total_bytes != len(source) or digest.hexdigest() != hashlib.sha256(source).hexdigest():
        raise ValueError('Hosted video bytes differ from the supplied source file')
    return {'transport': 'public_https_url', 'url_host': parsed.hostname,
            'url_sha256': hashlib.sha256(url.encode()).hexdigest(),
            'content_type': content_type, 'verified_remote_bytes': total_bytes,
            'remote_matches_local_source': True}


def build(manifest, segment):
    if not isinstance(segment['duration'], int) or not 4 <= segment['duration'] <= 15:
        raise ValueError('Local guard permits 4–15 seconds; server acceptance is recorded separately')
    if manifest['resolution'] != '768P' or manifest['ratio'] not in ('16:9', '9:16', 'adaptive'):
        raise ValueError('This project permits 768P with horizontal, vertical, or adaptive framing')
    if not 0 <= len(segment['images']) <= 5:
        raise ValueError('Text-only trials allow zero images; reference trials stay within the five-image free allowance')
    if sum(x['role'] == 'first_frame' for x in segment['images']) > 1:
        raise ValueError('Only one first frame is allowed')
    has_reference = any(x['role'] == 'reference_image' for x in segment['images']) or bool(segment.get('audio')) or bool(segment.get('videos'))
    if has_reference and any(x['role'] == 'first_frame' for x in segment['images']):
        raise ValueError('Reference media cannot be mixed with first-frame mode')
    prompt = Path(segment['prompt_file']).read_text(encoding='utf-8-sig').strip()
    for heading in ['【参考素材说明】', '【核心创意】', '【画面过程描述】', '【整体要求补充】']:
        if heading not in prompt:
            raise ValueError('Missing heading: ' + heading)
    content = [{'type': 'text', 'text': prompt}]
    images = []
    for item in segment['images']:
        if item['role'] not in ('reference_image', 'first_frame'):
            raise ValueError('Unrecognized local role')
        path = Path(item['path'])
        raw = path.read_bytes()
        encoded = base64.b64encode(raw).decode('ascii')
        assert base64.b64decode(encoded) == raw
        mime = mimetypes.guess_type(path.name)[0] or 'image/png'
        content.append({'type': 'image_url', 'image_url': {'url': f'data:{mime};base64,{encoded}'}, 'role': item['role']})
        images.append({'path': str(path), 'role': item['role'], 'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest()})
    audios = []
    for item in segment.get('audio', []):
        if item['role'] != 'reference_audio':
            raise ValueError('Unrecognized local audio role')
        path = Path(item['path'])
        raw = path.read_bytes()
        mime = mimetypes.guess_type(path.name)[0] or 'audio/wav'
        encoded = base64.b64encode(raw).decode('ascii')
        assert base64.b64decode(encoded) == raw
        content.append({'type': 'audio_url', 'audio_url': {'url': f'data:{mime};base64,{encoded}'}, 'role': item['role']})
        audios.append({'path': str(path), 'role': item['role'], 'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest()})
    videos = []
    if len(segment.get('videos', [])) > 3:
        raise ValueError('At most three reference videos are allowed')
    for item in segment.get('videos', []):
        if item['role'] != 'reference_video':
            raise ValueError('Unrecognized local video role')
        path = Path(item['path'])
        if path.suffix.lower() != '.mp4' or not 2 <= item['duration_seconds'] <= 15:
            raise ValueError('Reference video must be MP4 and between 2 and 15 seconds')
        raw = path.read_bytes()
        if len(raw) > 50 * 1024 * 1024:
            raise ValueError('Reference video exceeds 50 MB')
        if not item.get('url'):
            raise ValueError('AutoDL inline MP4 failed filename validation as .jpg; obtain and verify a hosted .mp4 URL before another submission')
        url_check = verify_video_url(item['url'], raw)
        content.append({'type': 'video_url', 'video_url': {'url': item['url']}, 'role': item['role']})
        videos.append({'path': str(path), 'role': item['role'], 'bytes': len(raw), 'duration_seconds': item['duration_seconds'], 'sha256': hashlib.sha256(raw).hexdigest(), **url_check})
    input_video_seconds = sum(item['duration_seconds'] for item in videos)
    if input_video_seconds > 15:
        raise ValueError('Total reference video duration exceeds 15 seconds')
    body = {k: manifest[k] for k in ['model', 'resolution', 'ratio']}
    body.update({'duration': segment['duration'], 'content': content})
    body_bytes = json.dumps(body, ensure_ascii=False).encode('utf-8')
    if len(body_bytes) > 64 * 1024 * 1024:
        raise ValueError('Request body exceeds 64 MB')
    audit = {k: body[k] for k in ['model', 'duration', 'resolution', 'ratio']}
    audit.update({'time': now(), 'prompt_file': segment['prompt_file'], 'prompt_sha256': hashlib.sha256(prompt.encode()).hexdigest(), 'prompt_characters': len(prompt), 'images': images, 'audio': audios, 'videos': videos, 'input_video_seconds': input_video_seconds, 'body_bytes': len(body_bytes), 'body_sha256': hashlib.sha256(json.dumps(body, ensure_ascii=False, sort_keys=True).encode()).hexdigest(), 'maximum_estimated_yuan': round((segment['duration'] + input_video_seconds) * 0.50, 4)})
    return body, audit


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--manifest', default=str(ROOT / 'prompts' / 'h3_ep01_参考图清单.json'))
    parser.add_argument('action', choices=['prepare', 'submit', 'query', 'fetch'])
    parser.add_argument('segment')
    args = parser.parse_args()
    manifest_path = Path(args.manifest)
    if not manifest_path.is_absolute():
        manifest_path = ROOT / manifest_path
    manifest = read(manifest_path)
    segment = next(x for x in manifest['segments'] if x['id'] == args.segment)
    run_dir = Path(manifest['run_directory'])
    folder = run_dir / segment['id']
    state_file = folder / 'state.json'
    state = read(state_file) if state_file.exists() else {'segment': segment['id'], 'status': 'not_submitted'}
    if args.action in ('prepare', 'submit'):
        body, audit = build(manifest, segment)
        save(folder / 'request_audit.json', audit)
        if args.action == 'prepare':
            print(json.dumps(audit, ensure_ascii=False, indent=2))
            return
        if state['status'] != 'not_submitted':
            raise RuntimeError('Submission already attempted; query/recover its recorded task instead of repeating POST')
        if segment.get('requires_retry_billing_confirmation') and not manifest.get('retry_billing_confirmed'):
            raise RuntimeError('Failed-attempt billing must be checked before another paid submission')
        if sum((x['duration'] + sum(v['duration_seconds'] for v in x.get('videos', []))) * 0.50 for x in manifest['segments']) > manifest['budget_yuan']:
            raise RuntimeError('Planned episode exceeds authorized budget')
        if segment.get('depends_on'):
            prior = read(run_dir / segment['depends_on'] / 'state.json')
            if prior['status'] != 'succeeded' or not Path(prior.get('local_file', '')).is_file():
                raise RuntimeError('Preceding segment must be succeeded and fetched')
        state.update({'status': 'submitting', 'submitted_at': now(), 'audit_sha256': audit['body_sha256'], 'maximum_estimated_yuan': audit['maximum_estimated_yuan']})
        save(state_file, state)
        save(folder / 'request_body.json', body)
        (folder / 'submitted_prompt.txt').write_text(body['content'][0]['text'] + '\n', encoding='utf-8')
        try:
            http, response = request('/api/v1/minimax/v2/video_generation', body)
        except Exception as error:
            state.update({'status': 'submission_unknown', 'transport_error_type': type(error).__name__})
            save(state_file, state)
            raise RuntimeError('Transport failed; acceptance is unknown. Do not resubmit.') from None
        save(folder / 'submit_response.json', {'http_status': http, 'response': response})
        task_id = response.get('task_id')
        state.update({'http_status': http})
        if task_id:
            state.update({'status': 'submitted', 'task_id': task_id})
        else:
            state.update({'status': 'rejected_without_task_id', 'error': response.get('error', response)})
        save(state_file, state)
        print(json.dumps(state, ensure_ascii=False))
        return

    task_id = state.get('task_id')
    if not task_id:
        raise RuntimeError('No recorded task ID')
    if args.action == 'query':
        http, response = request('/api/v1/minimax/v2/query/video_generation/' + task_id)
        save(folder / 'task_latest.json', {'time': now(), 'http_status': http, 'response': response})
        task = response.get('task', {})
        if task.get('status'):
            state.update({'status': task['status'], 'updated_at': now(), 'server_duration': task.get('duration'), 'server_resolution': task.get('resolution'), 'usage': task.get('usage'), 'error': task.get('error')})
            if task.get('content', {}).get('url'):
                state['video_url'] = task['content']['url']
            save(state_file, state)
        result = {k: state.get(k) for k in ['segment', 'status', 'task_id', 'server_duration', 'server_resolution', 'usage', 'error']}
        if response.get('error'):
            result['query_error'] = response['error']
        print(json.dumps(result, ensure_ascii=False))
        return

