        raise RuntimeError('Only a succeeded task can be fetched')
    output = Path(segment['output_file'])
    output.parent.mkdir(parents=True, exist_ok=True)
    if not output.is_file():
        partial = output.with_suffix('.partial.mp4')
        with urllib.request.urlopen(state['video_url'], timeout=55) as response, partial.open('wb') as target:
            while chunk := response.read(1024 * 1024):
