    # last frame (continuity reference for the next segment) + review frames
    subprocess.run(['ffmpeg', '-v', 'error', '-y', '-sseof', '-0.15', '-i', str(out), '-frames:v', '1', '-q:v', '2', str(d / 'last_frame.jpg')], check=True)
    subprocess.run(['ffmpeg', '-v', 'error', '-y', '-i', str(out), '-vf', 'fps=1.2,scale=448:-1,tile=4x3', '-frames:v', '1', '-q:v', '3', str(d / 'contact_sheet.jpg')], check=True)
    st['local_file'] = str(out); save(d / 'state.json', st)
    print(json.dumps({'segment': seg_id, 'file': str(out), 'bytes': out.stat().st_size}, ensure_ascii=False))


def wait(seg_id, limit=1500):
    t0 = time.time()
    while time.time() - t0 < limit:
        st = query(seg_id)
        print(f"[{int(time.time()-t0)}s] {st.get('status')}", flush=True)
        if st.get('status') == 'succeeded':
            fetch(seg_id); print(json.dumps({'usage': st.get('usage')}, ensure_ascii=False)); return
        if st.get('status') in ('failed', 'canceled', 'cancelled'):
            print(json.dumps({'error': st.get('error')}, ensure_ascii=False)); return
        time.sleep(20)
    print('still running; query again later')


if __name__ == '__main__':
    action, seg = sys.argv[1], sys.argv[2]
    {'submit': submit, 'query': lambda s: print(json.dumps(query(s), ensure_ascii=False)), 'fetch': fetch, 'wait': wait}[action](seg)
